import React, { useState } from 'react';
import { Calendar, ChevronDown, AlertCircle, User, MapPin, LayoutGrid, Download, Hash } from 'lucide-react';

const CollectionSchedule = () => {
  const [day, setDay] = useState('22');
  const [month, setMonth] = useState('MARCH');
  const [year, setYear] = useState('2026');
  const [viewMode, setViewMode] = useState('DAY');

  const scheduleLogs = [
    { id: 'SCH-1092', date: '22 MAR', time: '08:45', zone: 'NORTH_SEC', area: 'Hillside Drive', code: 'HSD-44', worker: 'RAVI_KUMAR', bins: '401, 405, 409', report: 'SENSOR_ERR' },
    { id: 'SCH-1104', date: '22 MAR', time: '13:20', zone: 'CENTRAL_HUB', area: 'Main Square', code: 'MSQ-01', worker: 'SITA_MAHESH', bins: '101, 102', report: null },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter">

      {/* 🛠️ COMPACT HEADER: THE SELECTORS */}
      <div className="flex flex-col lg:flex-row items-center gap-4">

        {/* VIEW SWITCHER (Sized Down) */}
        <div className="flex bg-[#47510B] p-1.5 rounded-2xl border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
          <button 
            onClick={() => setViewMode('DAY')}
            className={`px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all text-sm ${viewMode === 'DAY' ? 'bg-[#FFB6A9] text-[#47510B]' : 'text-white/40 hover:text-white'}`}
          >
            <Calendar size={18} /> DAY
          </button>
          <button 
            onClick={() => setViewMode('MONTH')}
            className={`px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all text-sm ${viewMode === 'MONTH' ? 'bg-[#A1AED1] text-[#47510B]' : 'text-white/40 hover:text-white'}`}
          >
            <LayoutGrid size={18} /> MONTH
          </button>
        </div>

        {/* COMPACT SELECTORS (Scrollable Dropdowns) */}
        <div className="flex bg-[#FFF24D] border-[4px] border-[#47510B] rounded-2xl px-4 py-2 items-center gap-6 shadow-[4px_4px_0_0_#47510B]">
          {viewMode === 'DAY' && (
            <div className="relative border-r-2 border-[#47510B]/20 pr-4">
              <select 
                value={day} 
                onChange={(e) => setDay(e.target.value)} 
                className="appearance-none bg-transparent pr-6 text-xl text-[#47510B] outline-none cursor-pointer font-[1000]"
                style={{ maxHeight: '150px' }} // Logic for internal scroll
              >
                {[...Array(31)].map((_, i) => <option key={i+1} value={i+1}>{String(i+1).padStart(2, '0')}</option>)}
              </select>
              <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
            </div>
          )}

          <div className="relative border-r-2 border-[#47510B]/20 pr-4">
             <select value={month} onChange={(e) => setMonth(e.target.value)} className="appearance-none bg-transparent pr-6 text-xl text-[#47510B] outline-none cursor-pointer">
                {['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
          </div>

          <div className="relative">
             <select value={year} onChange={(e) => setYear(e.target.value)} className="appearance-none bg-transparent pr-6 text-xl text-[#47510B] outline-none cursor-pointer">
                {['2025', '2026', '2027'].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
             <ChevronDown className="absolute right-0 top-1 text-[#47510B] pointer-events-none" size={18} />
          </div>
        </div>
      </div>

      {/* 🌊 DATA DISPLAY: THE REFINED MANIFEST */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-6 pb-10">
        {scheduleLogs.map((log) => (
          <div key={log.id} className="relative">
            <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-[30px]" />

            <div className="relative bg-white border-[4px] border-[#47510B] rounded-[30px] overflow-hidden flex flex-col md:flex-row hover:bg-[#FDFAD8] transition-all">

              {/* DATE/TIME (Blue Strip) */}
              <div className="bg-[#A1AED1] border-b-[4px] md:border-b-0 md:border-r-[4px] border-[#47510B] p-6 flex flex-col items-center justify-center min-w-[140px]">
                <p className="text-[10px] opacity-50 mb-1">{log.date}</p>
                <h2 className="text-4xl text-[#47510B] leading-none">{log.time}</h2>
                <span className="mt-2 text-[9px] bg-[#47510B] text-white px-2 py-0.5 rounded italic">ID_{log.id}</span>
              </div>

              {/* LOCATION & DATA PILLS */}
              <div className="flex-grow p-6 flex flex-col gap-4">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="flex items-center gap-1.5 mb-1">
                      <MapPin size={16} className="text-[#AB1717]" />
                      <span className="text-sm text-[#AB1717]">{log.zone} // {log.code}</span>
                    </div>
                    <h1 className="text-4xl text-[#47510B] leading-none">{log.area}</h1>
                  </div>

                  {/* COMPACT PILLS */}
                  <div className="flex gap-3">
                    <div className="bg-[#47510B] text-white px-4 py-2 rounded-xl flex items-center gap-3 border-2 border-white shadow-[3px_3px_0_0_#47510B]">
                      <User size={18} className="text-[#FFB6A9]" />
                      <span className="text-sm">{log.worker}</span>
                    </div>
                    <div className="bg-[#FFF24D] border-[2px] border-[#47510B] px-4 py-2 rounded-xl flex items-center gap-3 shadow-[3px_3px_0_0_#47510B]">
                      <Hash size={18} className="text-[#47510B]" />
                      <span className="text-sm font-mono">{log.bins}</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* REPORT STATUS */}
              <div className={`p-6 md:w-32 flex items-center justify-center border-t-[4px] md:border-t-0 md:border-l-[4px] border-[#47510B] ${log.report ? 'bg-[#AB1717] animate-pulse' : 'bg-transparent'}`}>
                {log.report ? (
                  <AlertCircle size={32} className="text-white" />
                ) : (
                  <div className="w-3 h-3 rounded-full bg-[#CAD23C]" />
                )}
              </div>

            </div>
          </div>
        ))}
      </div>

      {/* 🧭 FOOTER ACTION BAR */}
      <div className="bg-[#47510B] p-4 rounded-full flex justify-between items-center border-[4px] border-white shadow-[6px_6px_0_0_#A1AED1]">
         <p className="text-white text-lg ml-6 italic">
            VIEWING: <span className="text-[#FFB6A9]">{viewMode === 'DAY' ? `${day} ${month}` : `MANIFEST_${month}`}</span>
         </p>
         <button className="bg-[#FFF24D] text-[#47510B] px-8 py-2.5 rounded-full text-sm font-[1000] border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#47510B] flex items-center gap-2 hover:-translate-y-0.5 active:translate-y-0 transition-all mr-2">
            <Download size={18} /> EXPORT_CSV
         </button>
      </div>

    </div>
  );
};

export default CollectionSchedule;
